pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testRegression_property() public {
        bool ok;
        try c.assertionDisputedCallback(bytes32(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        address attacker = address(0x1234);
        vm.prank(attacker);
        try c.assertionDisputedCallback(bytes32(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Reference should revert when caller is not the optimistic asserter");
    }
}
